style.css:
@-moz-document domain("drime.cloud") {
:root {
        /* Override accent variables if they exist */
        --primary-color: #444444 !important; /* muted dark grey */
        --accent-color: #444444 !important;
        --success-color: #444444 !important;
    }

    /* Links */
    a,
    a:visited {
        color: #444444 !important;
    }

    a:hover,
    a:focus {
        color: #666666 !important; /* slightly lighter grey on hover */
    }

    /* Buttons */
    button,
    .btn,
    .button,
    input[type="submit"],
    input[type="button"] {
        background-color: #444444 !important;
        border-color: #444444 !important;
        color: #ffffff !important;
    }

    button:hover,
    .btn:hover,
    .button:hover,
    input[type="submit"]:hover,
    input[type="button"]:hover {
        background-color: #666666 !important;
        border-color: #666666 !important;
    }

    /* Highlights, badges, notifications */
    .badge,
    .tag,
    .label,
    .highlight,
    .alert-success {
        background-color: #444444 !important;
        border-color: #444444 !important;
        color: #ffffff !important;
    }

    /* Progress bars or other accent UI */
    .progress-bar,
    .accent,
    .primary {
        background-color: #444444 !important;
    }
}
